import {GESTURES,uid,fresh,newSet,score,events,tally,wins,closeRally,undo,validSetScore,validate} from './model.js';
const KEY='scouting-pallavolo-v1',app=document.querySelector('#app'),modal=document.querySelector('#modal');
let data,view='partite',setIndex=0,gesture='serve',statsScope='match',storageBlocked=false;
try {const raw=localStorage.getItem(KEY);data=raw?validate(JSON.parse(raw)):fresh();}catch{data=fresh();storageBlocked=true;}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const active=()=>data.matches.find(m=>m.id===data.activeId);
const name=p=>`${p.first} ${p.last}${p.nickname?' ('+p.nickname+')':''}`.trim();
function syncMatchPlayers(){let changed=false;const team=new Map(data.team.players.map(p=>[p.id,p]));for(const match of data.matches)for(const player of match.players){const current=team.get(player.id);if(!current)continue;for(const key of ['first','last','number','role','nickname']){const value=key==='nickname'?(current.nickname||''):current[key];if(player[key]!==value){player[key]=value;changed=true;}}}return changed;}
if(!storageBlocked){try{if(syncMatchPlayers())localStorage.setItem(KEY,JSON.stringify(data));}catch{storageBlocked=true;}}
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short',year:'numeric'});
const btn=(action,label,cls='',extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
const empty=(title,text,action)=>`<div class="empty"><span class="empty-mark">V•</span><h2>${title}</h2><p>${text}</p>${action||''}</div>`;
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=error?'visible error':'visible';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4000);}
function mutate(fn){
 if(storageBlocked){toast('Salvataggio non disponibile. Esporta i dati o ripristina un backup prima di continuare.',true);return false;}
 const previous=structuredClone(data);
 try{fn();syncMatchPlayers();localStorage.setItem(KEY,JSON.stringify(data));render();return true;}catch(e){data=previous;toast('Modifica non salvata: '+e.message,true);return false;}
}
function showDialog(html){document.querySelector('#modal-content').innerHTML=html;modal.showModal();}
function dialogHeader(title){return `<div class="dialog-title"><h2>${title}</h2>${btn('cancel','×','icon-button','aria-label="Chiudi"')}</div>`;}
function changeView(v){view=v;render();}
function render(){
 const oldMatrix=document.querySelector('.matrix-wrap');
 const position=oldMatrix?{top:oldMatrix.scrollTop,left:oldMatrix.scrollLeft}:null;
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view||(view==='scout'||view==='stats')&&b.dataset.view==='partite'));
 if(view==='scout'&&active())renderScout();else if(view==='stats'&&active())renderStats();else if(view==='squadra')renderTeam();else if(view==='dati')renderData();else renderMatches();
 const newMatrix=document.querySelector('.matrix-wrap');
 if(position&&newMatrix){newMatrix.scrollTop=position.top;newMatrix.scrollLeft=position.left;}
}
function renderMatches(){
 app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">IL TUO BORDOCAMPO</p><h1>Ogni tocco conta.</h1><p class="muted">La partita, i tuoi atleti, tutte le azioni.</p></div>${btn('new-match','+ Nuova partita','primary')}</div>
 <div class="overview"><div><small>PARTITE</small><strong>${data.matches.length}</strong></div><div><small>ATLETI IN ROSA</small><strong>${data.team.players.length}</strong></div><div class="overview-note"><span class="dot"></span><span>Salvataggio sul dispositivo<br><small>Pronto per il campo, anche offline</small></span></div></div>
 <div class="section-heading"><h2>Le tue partite</h2><span class="muted">${esc(data.team.name)}</span></div>
 ${data.matches.length?`<div class="match-grid">${[...data.matches].reverse().map(m=>{const w=wins(m);return `<article class="match-card"><div class="card-meta"><span>${date(m.date)}</span><span class="pill ${m.completed?'':'live'}">${m.completed?'Terminata':'In corso'}</span></div><h3>${esc(m.home)} <span class="versus">vs</span> ${esc(m.away)}</h3><div class="card-score">${w.home}<span>:</span>${w.away}<small>SET</small></div><div class="set-scores">${m.sets.map((s,i)=>{const p=score(s);return `<span>Set ${i+1} <b>${p.home}–${p.away}</b></span>`;}).join('')}</div><div class="card-bottom"><span class="muted">${m.players.length} convocati</span>${btn('open-match',m.completed?'Rivedi partita →':'Riprendi scout →','text-button',`data-id="${m.id}"`)}</div></article>`;}).join('')}</div>`:empty('La prossima partita inizia qui.','Inserisci la rosa, scegli i convocati e scendi in campo.',btn('team','Prepara la squadra','primary'))}`;
}
function renderTeam(){app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">LA TUA ROSA</p><h1>${esc(data.team.name)}</h1><p class="muted">Crea gli atleti una volta. Convocali nelle prossime partite.</p></div><div class="actions">${btn('rename-team','Nome squadra','secondary')}${btn('add-player','+ Aggiungi atleta','primary')}</div></div>
 ${data.team.players.length?`<div class="roster">${[...data.team.players].sort((a,b)=>Number(a.number)-Number(b.number)).map(p=>`<article class="player-card"><span class="jersey">${esc(p.number||'–')}</span><div><h3>${esc(name(p))}</h3><p class="muted">${esc(p.role||'Ruolo non indicato')}</p></div>${btn('edit-player','Modifica','text-button',`data-id="${p.id}"`)}</article>`).join('')}</div>`:empty('La tua squadra prende forma.','Nome, cognome, ruolo e numero di maglia.',btn('add-player','+ Primo atleta','primary'))}`;}
function renderData(){app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">TUTTO SOTTO CONTROLLO</p><h1>Dati e guida</h1><p class="muted">Scouting Pallavolo · versione 1.0.0</p></div></div><div class="two-columns"><section class="panel"><h2>Il tuo backup</h2><p>I dati restano in questo browser e su questo dispositivo. Non vengono sincronizzati tra dispositivi. La cancellazione dei dati del sito rimuove le partite.</p><div class="actions">${btn('export','Esporta backup JSON','primary')}${btn('import','Importa backup','secondary')}</div><input id="backup-file" type="file" accept=".json,application/json" hidden><p class="muted">L’importazione sostituisce rosa e partite, dopo conferma.</p>${storageBlocked?'<p class="warning">I dati precedenti non sono leggibili o il browser non consente il salvataggio. Il dato originale non è stato sovrascritto. Esporta il dato originale per recuperarlo.</p>'+btn('export-raw','Esporta dato originale','secondary'):''}</section><section class="panel"><h2>Al bordo del campo</h2><ol><li>Crea una partita con massimo 14 convocati.</li><li>Per ogni set attiva <b>T</b> sugli atleti in campo: salgono in cima. Cambia i flag quando fai una sostituzione.</li><li>Tocca la cella di un atleta: ogni tocco registra un’azione. Puoi ripetere gesto e atleta nello stesso rally.</li><li>Chiudi con <b>Punto casa</b> o <b>Punto trasferta</b>. I gesti non assegnano automaticamente il punteggio.</li><li><b>Annulla</b> rimuove l’ultima azione; se il rally è appena chiuso, lo riapre e toglie il punto.</li><li>Chiudi il set, poi passa al successivo. Le T del nuovo set sono indipendenti.</li></ol></section><section class="panel"><h2>I codici</h2><p>Battuta e muro: <b>+</b> punto diretto, <b>=</b> errore.</p><p>Ricezione e attacco: <b>+</b>, <b>=</b>, <b>#</b>. Il report mantiene i conteggi distinti per ciascun codice.</p><p class="muted">Il numero totale di azioni è calcolato dalla PWA. Difesa e alzata escluse.</p></section><section class="panel"><h2>Installala e usala offline</h2><p>Apri il sito online una prima volta e attendi l’indicazione “Offline pronto”. Su iPhone: Condividi → Aggiungi alla schermata Home. Su Android/desktop: Installa app dal menu del browser.</p><p>La prima apertura richiede Internet. In seguito puoi registrare partite anche senza connessione.</p><p>Da Risultati puoi stampare il riepilogo o salvarlo in PDF scegliendo “Salva come PDF” nella finestra di stampa.</p></section></div>`;}
function renderScout(){
 const m=active();setIndex=Math.min(setIndex,m.sets.length-1);const s=m.sets[setIndex],p=score(s),w=wins(m),locked=s.closed||m.completed;
 const list=events(s),players=[...m.players].sort((a,b)=>Number(s.starters.includes(b.id))-Number(s.starters.includes(a.id))||Number(a.number)-Number(b.number));
 app.innerHTML=`<div class="scout-heading"><div>${btn('matches','← Partite','text-button')}<h1>${esc(m.home)} <span class="versus">vs</span> ${esc(m.away)}</h1><p class="muted">${date(m.date)} · Scout: ${esc(m[m.ourSide])}</p></div><div class="actions">${btn('results','Risultati ↗','secondary')}${btn('export','Backup','secondary')}</div></div>
 <section class="scoreboard"><div class="score-side"><small>CASA</small><h2>${esc(m.home)}</h2><strong>${p.home}</strong>${btn('point','+ Punto casa','primary',`data-side="home" ${locked?'disabled':''}`)}</div><div class="score-center"><span class="pill ${locked?'':'live'}">${m.completed?'TERMINATA':s.closed?'SET CHIUSO':'LIVE SCOUT'}</span><b>SET ${setIndex+1}</b><span>${w.home} : ${w.away}</span><small>set vinti</small></div><div class="score-side"><small>TRASFERTA</small><h2>${esc(m.away)}</h2><strong>${p.away}</strong>${btn('point','+ Punto trasferta','secondary',`data-side="away" ${locked?'disabled':''}`)}</div></section>
 <div class="set-toolbar"><div class="set-tabs" role="group" aria-label="Set">${m.sets.map((ss,i)=>{const pp=score(ss);return btn('set',`Set ${i+1}<small>${pp.home}–${pp.away}</small>`,i===setIndex?'selected':'',`data-index="${i}"`);}).join('')}</div><div class="actions">${btn('undo','↶ Annulla','secondary',locked||!s.pending.length&&!s.rallies.length?'disabled':'')}${!locked?btn('close-set','Chiudi set','secondary'):!m.completed&&setIndex===m.sets.length-1?btn('next-set','+ Set successivo','primary'):''}${s.closed&&!m.completed&&setIndex===m.sets.length-1?btn('reopen-set','Riapri set','text-button'):''}${!m.completed?btn('finish','Termina partita','text-button'):btn('resume','Riapri partita','text-button')}</div></div>
 <section class="rally-panel"><div><span class="eyebrow">RALLY ${s.rallies.length+1}</span><span class="muted">${s.pending.length} azioni da chiudere${locked?' · sola lettura':''}</span></div><div class="rally-events">${s.pending.length?s.pending.map(e=>{const pl=m.players.find(x=>x.id===e.playerId),g=GESTURES.find(x=>x.id===e.gesture);return `<span class="event-chip"><b>${esc(pl.number||name(pl))}</b> ${g.short} <strong>${e.code}</strong></span>`;}).join(''):'<span class="muted">Tocca le celle, poi assegna il punto.</span>'}</div></section>
 <div class="matrix-heading"><h2>Scout per atleta</h2><span class="muted">T = in campo · ogni tocco aggiunge 1</span></div><div class="gesture-tabs">${GESTURES.map(g=>btn('gesture',g.name,g.id===gesture?'selected':'',`data-gesture="${g.id}"`)).join('')}</div>
 <div class="matrix-wrap"><table class="matrix" data-focus="${gesture}"><thead><tr><th rowspan="2" class="t-col">T</th><th rowspan="2" class="name-col">Atleta</th>${GESTURES.map(g=>`<th colspan="${g.codes.length}" class="gesture-col ${g.id}">${g.name}<small>tot. ${tally(list,null,g.id)}</small></th>`).join('')}</tr><tr>${GESTURES.map(g=>g.codes.map(c=>`<th class="gesture-col ${g.id} code-${c==='='?'error':c==='+'?'plus':'hash'}">${c}</th>`).join('')).join('')}</tr></thead><tbody>${players.map(pl=>`<tr class="${s.starters.includes(pl.id)?'on-court':''}"><td class="t-col"><input type="checkbox" aria-label="In campo ${esc(name(pl))}" data-starter="${pl.id}" ${s.starters.includes(pl.id)?'checked':''} ${locked?'disabled':''}></td><th scope="row" class="name-col"><span class="player-number">${esc(pl.number||'–')}</span><span>${esc(name(pl))}<small>${esc(pl.role)}</small></span></th>${GESTURES.map(g=>g.codes.map(c=>`<td class="gesture-col ${g.id}">${btn('event',tally(list,pl.id,g.id,c),'count-button',`data-player="${pl.id}" data-gesture="${g.id}" data-code="${c}" aria-label="${esc(name(pl))}, ${g.name} ${c}" ${locked?'disabled':''}`)}</td>`).join('')).join('')}</tr>`).join('')}</tbody></table></div>
 <p class="matrix-note">Battuta e muro: + punto, = errore. Ricezione e attacco: + / = / #. I totali includono le azioni del rally aperto.</p>
 <details class="panel rally-history"><summary>Rally registrati · ${s.rallies.length}</summary>${s.rallies.length?[...s.rallies].reverse().map((r,i)=>`<div class="history-row"><b>#${s.rallies.length-i}</b><span>Punto ${esc(m[r.winner])}</span><small>${r.events.map(e=>{const pl=m.players.find(x=>x.id===e.playerId);return `${esc(pl.number||name(pl))} ${GESTURES.find(g=>g.id===e.gesture).short}${e.code}`;}).join(' · ')||'Nessuna azione rilevata'}</small></div>`).join(''):'<p class="muted">Nessun rally chiuso.</p>'}</details>`;
}

function setAnalysis(m,scope){
 const indexed=scope==='match'?m.sets.map((s,i)=>({s,i})):[{s:m.sets[Number(scope)],i:Number(scope)}];
 const labels={serve:'Battuta',receive:'Ricezione',attack:'Attacco',block:'Muro'};
 const keys=['serve','receive','attack','block'];
 const series=indexed.map(({s,i})=>{
  const ev=events(s),p=score(s),ours=m.ourSide,theirs=ours==='home'?'away':'home';
  let home=0,away=0;
  const path=[{h:0,a:0},...s.rallies.map(r=>{if(r.winner==='home')home++;else away++;return {h:home,a:away};})];
  return {i,s,ev,p,path,ours:p[ours],theirs:p[theirs],positive:keys.map(k=>tally(ev,null,k,'+')),errors:keys.map(k=>tally(ev,null,k,'='))};
 });
 const svg=d=>{
  const w=650,h=168,l=34,r=18,t=18,b=28,max=Math.max(5,...d.path.flatMap(p=>[p.h,p.a]));
  const xy=(v,i)=>[l+(w-l-r)*i/Math.max(1,d.path.length-1),h-b-(h-t-b)*v/max];
  const points=k=>d.path.map((p,i)=>xy(p[k],i).map(n=>n.toFixed(1)).join(',')).join(' ');
  const ticks=[0,Math.ceil(max/2),max];
  return '<svg class="set-trend" viewBox="0 0 650 168" role="img" aria-label="Andamento dei punti casa e trasferta per rally">' +
   ticks.map(v=>{const y=xy(v,0)[1];return '<line x1="'+l+'" y1="'+y+'" x2="'+(w-r)+'" y2="'+y+'" stroke="#63756c" stroke-opacity=".24"/><text x="4" y="'+(y+4)+'" fill="currentColor" font-size="11">'+v+'</text>';}).join('')+
   '<polyline points="'+points('h')+'" fill="none" stroke="#9bcc33" stroke-width="3" stroke-linejoin="round"/>'+
   '<polyline points="'+points('a')+'" fill="none" stroke="#6da7e1" stroke-width="3" stroke-linejoin="round"/>'+
   '<text x="'+l+'" y="164" fill="currentColor" font-size="11">Inizio</text><text x="540" y="164" fill="currentColor" font-size="11">'+(d.path.length-1)+' rally chiusi</text></svg>';
 };
 const sum=(arr,i)=>arr.reduce((n,d)=>n+d[i],0);
 const cards=series.map(d=>'<section class="set-analysis-card"><div class="set-analysis-head"><h3>Set '+(d.i+1)+'</h3><strong>'+d.p.home+' – '+d.p.away+'</strong><span>'+(d.s.closed?'Concluso':'In corso')+'</span></div><div class="set-analysis-meta"><span>Casa <b class="home-mark">—</b></span><span>Trasferta <b class="away-mark">—</b></span></div>'+svg(d)+'<div class="set-analysis-totals"><span>Azioni registrate <b>'+d.ev.length+'</b></span><span>Punti nostra squadra <b>'+d.ours+'</b></span><span>Errori battuta/muro <b>'+(d.errors[0]+d.errors[3])+'</b></span></div></section>').join('');
 const rows=keys.map((k,i)=>'<tr><th>'+labels[k]+'</th>'+series.map(d=>'<td>'+d.positive[i]+' / '+d.errors[i]+'</td>').join('')+'<td>'+sum(series.map(d=>d.positive),i)+' / '+sum(series.map(d=>d.errors),i)+'</td></tr>').join('');
 return '<section class="set-analysis"><div class="set-analysis-title"><p class="eyebrow">REPORT PARTITA · ANALISI PER SET</p><h2>Analisi per set</h2><p class="muted">Andamento del punteggio e fondamentali rilevati · '+esc(m.home)+' vs '+esc(m.away)+'</p></div><div class="set-analysis-cards">'+cards+'</div><h3>Confronto tra i set</h3><div class="report-table-wrap"><table class="report-table set-compare"><thead><tr><th>Fondamentale</th>'+series.map(d=>'<th>Set '+(d.i+1)+'</th>').join('')+'<th>Totale</th></tr></thead><tbody>'+rows+'</tbody></table></div><p class="muted set-analysis-footnote">Valori: + / = registrati. Ricezione e attacco mantengono anche il codice # nel dettaglio atleti. I grafici mostrano i punti assegnati a fine rally; non attribuiscono automaticamente un punto o un errore tecnico agli atleti. Un set aperto mostra dati provvisori.</p></section>';
}

function report(m,scope){const sets=scope==='match'?m.sets:[m.sets[Number(scope)]],list=sets.flatMap(events),w=wins(m),total=list.length;
 return `<div class="report-heading"><p class="eyebrow">REPORT PARTITA · SCOUTING PALLAVOLO</p><h1>${esc(m.home)} – ${esc(m.away)}</h1><p>${date(m.date)} · ${m.completed?'Partita terminata':'Rilevazione in corso'} · ${scope==='match'?'Intera partita':'Set '+(Number(scope)+1)}</p><h2>${w.home} : ${w.away} <small>set vinti</small></h2><div class="set-scores">${m.sets.map((s,i)=>{const p=score(s);return `<span>Set ${i+1} <b>${p.home}–${p.away}</b>${s.closed?'':' (aperto)'}</span>`;}).join('')}</div></div><div class="kpi-grid"><div class="panel"><small>AZIONI RILEVATE</small><strong>${total}</strong></div><div class="panel"><small>ACE · BATTUTA +</small><strong>${tally(list,null,'serve','+')}</strong></div><div class="panel"><small>MURI PUNTO · MURO +</small><strong>${tally(list,null,'block','+')}</strong></div><div class="panel"><small>ERRORI BATTUTA + MURO</small><strong>${tally(list,null,'serve','=')+tally(list,null,'block','=')}</strong></div></div><h2>Dettaglio squadra · ${esc(m[m.ourSide])}</h2><div class="report-table-wrap"><table class="report-table"><thead><tr><th rowspan="2">Atleta</th>${GESTURES.map(g=>`<th colspan="${g.codes.length+1}">${g.name}</th>`).join('')}</tr><tr>${GESTURES.map(g=>`<th>nr</th>${g.codes.map(c=>`<th>${c}</th>`).join('')}`).join('')}</tr></thead><tbody>${m.players.map(pl=>`<tr><th>${esc(pl.number)} · ${esc(name(pl))}</th>${GESTURES.map(g=>`<td>${tally(list,pl.id,g.id)}</td>${g.codes.map(c=>`<td>${tally(list,pl.id,g.id,c)}</td>`).join('')}`).join('')}</tr>`).join('')}</tbody><tfoot><tr><th>Totale squadra</th>${GESTURES.map(g=>`<td>${tally(list,null,g.id)}</td>${g.codes.map(c=>`<td>${tally(list,null,g.id,c)}</td>`).join('')}`).join('')}</tr></tfoot></table></div><p class="muted">nr = totale automatico. Battuta/muro + = punto diretto; battuta/muro = = errore. Ricezione e attacco riportati per codice, senza attribuzioni aggiuntive.</p>${setAnalysis(m,scope)}${sets.some(s=>s.pending.length)?'<p class="warning">Sono incluse azioni di un rally ancora aperto. Chiudilo per consolidare il report.</p>':''}`;
}
function renderStats(){const m=active();app.innerHTML=`<div class="page-heading"><div>${btn('scout','← Torna allo scout','text-button')}<h1>Risultati e squadra</h1></div><div class="actions report-actions"><label for="stats-scope">Intervallo</label><select id="stats-scope"><option value="match">Intera partita</option>${m.sets.map((s,i)=>`<option value="${i}">Set ${i+1}</option>`).join('')}</select>${btn('print','Stampa / Salva PDF','primary')}</div></div><div class="report">${report(m,statsScope)}</div>`;document.querySelector('#stats-scope').value=statsScope;}
function playerDialog(id){const p=data.team.players.find(x=>x.id===id)||{first:'',last:'',number:'',role:'',nickname:''};showDialog(`${dialogHeader(id?'Modifica atleta':'Nuovo atleta')}<form id="player-form" data-id="${id||''}"><div class="form-grid"><label>Nome<input name="first" required maxlength="50" value="${esc(p.first)}" autocomplete="given-name"></label><label>Cognome<input name="last" required maxlength="50" value="${esc(p.last)}" autocomplete="family-name"></label><label>Soprannome (facoltativo)<input name="nickname" maxlength="40" value="${esc(p.nickname||'')}" autocomplete="off"></label><label>Numero maglia<input name="number" type="number" min="0" max="99" required value="${esc(p.number)}"></label><label>Ruolo<select name="role">${['Palleggiatore','Opposto','Schiacciatore','Centrale','Libero','Altro'].map(r=>`<option ${p.role===r?'selected':''}>${r}</option>`).join('')}</select></label></div><p class="muted">Le modifiche anagrafiche si aggiornano anche nelle partite già create.</p><div class="dialog-actions">${id?btn('remove-player','Rimuovi dalla rosa','danger',`data-id="${id}"`):''}<button class="primary">Salva atleta</button></div></form>`);}
function matchDialog(){if(!data.team.players.length){changeView('squadra');playerDialog();return;}const today=new Date(),local=new Date(today.getTime()-today.getTimezoneOffset()*60000).toISOString().slice(0,10);showDialog(`${dialogHeader('Nuova partita')}<form id="match-form"><div class="form-grid"><label>Squadra casa<input name="home" value="${esc(data.team.name)}" maxlength="100" required></label><label>Squadra trasferta<input name="away" maxlength="100" placeholder="Nome avversari" required></label><label>Data<input name="date" type="date" value="${local}" required></label><label>La nostra squadra è<select name="ourSide"><option value="home">Casa</option><option value="away">Trasferta</option></select></label></div><h3>Convocati <span id="selected-count"></span> <small>massimo 14</small></h3><div class="callups">${data.team.players.map((p,i)=>`<label><input type="checkbox" name="player" value="${p.id}" ${i<14?'checked':''}><b>${esc(p.number)}</b> ${esc(name(p))}<small>${esc(p.role)}</small></label>`).join('')}</div><p class="muted">Tutti i convocati saranno visibili in ogni set. Imposta le T nello scout.</p><div class="dialog-actions"><button class="primary">Inizia la partita →</button></div></form>`);updateCount();}
function updateCount(){const count=document.querySelectorAll('input[name="player"]:checked').length,el=document.querySelector('#selected-count');if(el)el.textContent=count;}
function download(content,file,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const actions={
 'cancel':()=>modal.close(),'matches':()=>changeView('partite'),'team':()=>changeView('squadra'),'scout':()=>changeView('scout'),'results':()=>{statsScope='match';changeView('stats');},
 'new-match':matchDialog,'add-player':()=>playerDialog(),'edit-player':b=>playerDialog(b.dataset.id),
 'rename-team':()=>showDialog(`${dialogHeader('Nome squadra')}<form id="team-form"><label>Nome della squadra<input name="name" required maxlength="100" value="${esc(data.team.name)}"></label><div class="dialog-actions"><button class="primary">Salva</button></div></form>`),
 'remove-player':b=>{if(confirm('Rimuovere l’atleta dalla rosa? I dati delle partite restano disponibili.'))if(mutate(()=>data.team.players=data.team.players.filter(p=>p.id!==b.dataset.id)))modal.close();},
 'open-match':b=>{if(mutate(()=>data.activeId=b.dataset.id)){setIndex=active().sets.length-1;changeView('scout');}},
 'set':b=>{setIndex=Number(b.dataset.index);render();},'gesture':b=>{gesture=b.dataset.gesture;render();},
 'event':b=>{const m=active(),s=m.sets[setIndex];if(s.closed||m.completed)return;mutate(()=>s.pending.push({id:uid(),playerId:b.dataset.player,gesture:b.dataset.gesture,code:b.dataset.code,at:new Date().toISOString()}));},
 'point':b=>{const m=active(),s=m.sets[setIndex];if(s.closed||m.completed)return;mutate(()=>closeRally(s,b.dataset.side));},
 'undo':()=>{const m=active();if(!m.completed)mutate(()=>undo(m.sets[setIndex]));},
 'close-set':()=>{const m=active(),s=m.sets[setIndex];if(s.pending.length){toast('Chiudi prima il rally assegnando il punto.',true);return;}const p=score(s);if(p.home===p.away){toast('Un set non può terminare in parità.',true);return;}if(confirm(`Chiudere il set ${setIndex+1} sul ${p.home}–${p.away}?${validSetScore(s,setIndex)?'':' Il punteggio non è quello di un set standard: verifica prima di confermare.'}`))mutate(()=>{s.closed=true;const w=wins(m);if(w.home===3||w.away===3||m.sets.length===5)m.completed=true;});},
 'next-set':()=>{const m=active();if(m.completed||m.sets.length>=5||!m.sets.at(-1).closed)return;if(mutate(()=>m.sets.push(newSet()))){setIndex=m.sets.length-1;render();}},
 'reopen-set':()=>{const m=active();if(confirm('Riaprire l’ultimo set per correggerlo?'))mutate(()=>m.sets.at(-1).closed=false);},
 'finish':()=>{const m=active();if(m.sets.some(s=>s.pending.length)){toast('Chiudi il rally prima di terminare la partita.',true);return;}if(confirm('Terminare la partita con il risultato attuale? I set aperti restano indicati nel report.'))mutate(()=>m.completed=true);},
 'resume':()=>{if(confirm('Riaprire la partita per modificare lo scout?'))mutate(()=>active().completed=false);},
 'export':()=>download(JSON.stringify(data,null,2),`scouting-backup-${new Date().toISOString().slice(0,10)}.json`),
 'export-raw':()=>{try{download(localStorage.getItem(KEY)||'{}','scouting-dato-originale.json');}catch{toast('Il browser non consente di leggere i dati.',true);}},
 'import':()=>document.querySelector('#backup-file').click(),
 'print':()=>{document.querySelector('#print-report').innerHTML=report(active(),statsScope);window.print();}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action], [data-view]');if(!b||b.disabled)return;if(b.dataset.view){changeView(b.dataset.view);return;}actions[b.dataset.action]?.(b);});
document.addEventListener('change',async e=>{
 if(e.target.matches('[data-starter]')){const m=active(),s=m.sets[setIndex],id=e.target.dataset.starter;if(s.closed||m.completed)return;mutate(()=>s.starters=e.target.checked?[...s.starters,id]:s.starters.filter(x=>x!==id));}
 if(e.target.name==='player'){if(document.querySelectorAll('input[name="player"]:checked').length>14){e.target.checked=false;toast('Massimo 14 convocati.',true);}updateCount();}
 if(e.target.id==='stats-scope'){statsScope=e.target.value;render();}
 if(e.target.id==='backup-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Il backup supera 20 MB.');const incoming=validate(JSON.parse(await file.text()));if(confirm(`Importare ${incoming.matches.length} partite e ${incoming.team.players.length} atleti? Sostituirà tutti i dati presenti su questo dispositivo. Esporta prima un backup se vuoi conservarli.`)){localStorage.setItem(KEY,JSON.stringify(incoming));data=incoming;storageBlocked=false;view='partite';render();toast('Backup importato.');}}catch(err){toast(err.message,true);}e.target.value='';}
});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f);
 if(f.id==='player-form'){const p={id:f.dataset.id||uid(),first:String(fd.get('first')).trim(),last:String(fd.get('last')).trim(),number:String(fd.get('number')),role:String(fd.get('role')),nickname:String(fd.get('nickname')||'').trim()};if(!p.first||!p.last){toast('Inserisci nome e cognome.',true);return;}if(data.team.players.some(x=>x.id!==p.id&&x.number===p.number)){toast('Numero di maglia già presente nella rosa.',true);return;}if(mutate(()=>{const i=data.team.players.findIndex(x=>x.id===p.id);if(i<0)data.team.players.push(p);else data.team.players[i]=p;}))modal.close();}
 if(f.id==='team-form'){const n=String(fd.get('name')).trim();if(n&&mutate(()=>data.team.name=n))modal.close();}
 if(f.id==='match-form'){const ids=fd.getAll('player'),home=String(fd.get('home')).trim(),away=String(fd.get('away')).trim();if(!home||!away||!ids.length||ids.length>14){toast('Inserisci le due squadre e da 1 a 14 convocati.',true);return;}const m={id:uid(),home,away,date:fd.get('date'),ourSide:fd.get('ourSide'),players:structuredClone(data.team.players.filter(p=>ids.includes(p.id))),sets:[newSet()],completed:false};if(mutate(()=>{data.matches.push(m);data.activeId=m.id;})){modal.close();setIndex=0;changeView('scout');}}
});
async function setupOffline(){const el=document.querySelector('#network');if(!('serviceWorker'in navigator)){el.textContent='Solo online';return;}try{await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;el.textContent=navigator.onLine?'Offline pronto':'Sei offline';}catch{el.textContent='Offline non disponibile';}}
window.addEventListener('online',setupOffline);window.addEventListener('offline',()=>document.querySelector('#network').textContent='Sei offline');
window.addEventListener('storage',e=>{if(e.key===KEY){storageBlocked=true;toast('Dati modificati in un’altra scheda. Ricarica prima di continuare.',true);}});
render();setupOffline();if(storageBlocked){changeView('dati');toast('Dati non leggibili: consulta Dati e guida.',true);}
